<template><view class="page"><view class="intro"><text class="title">我的作品</text><text class="sub">查看生成结果、审核状态与博物馆审批出处</text></view><view v-if="loading" class="empty">加载中…</view><view v-else-if="!assets.length" class="empty">还没有作品，去开始第一件创作吧。</view><view v-else class="list"><view v-for="item in assets" :key="item.id" class="asset"><image v-if="item.assetType==='image'&&item.previewUrl" :src="imageUrl(item.previewUrl)" mode="aspectFill" class="cover"/><view v-else class="model">3D</view><view class="body"><view class="row"><text class="name">{{ item.title || '未命名作品' }}</text><text class="status" :class="item.status">{{ statusText(item.status) }}</text></view><text class="meta">{{ item.assetType==='model'?'3D 模型':'AI 图片' }} · {{ item.format?.toUpperCase() || 'PNG' }}</text><text v-if="source(item)" class="source">审批出处：{{ source(item) }}</text><view class="actions"><button v-if="item.assetType==='model'" size="mini" @tap="preview(item)">查看 3D</button><button size="mini" @tap="copy(item)">复制作品编号</button></view></view></view></view></view></template>
<script setup lang="ts">import { onMounted, ref } from 'vue';import { getAssets } from '../../api/creative';import { requireSession } from '../../utils/session';import { imageUrl,statusText } from '../../utils/format';const assets=ref<any[]>([]);const loading=ref(true);const source=(a:any)=>{const tags=String(a.tags||'');const m=tags.match(/审批出处=([^,，;；]+)/);return m?.[1]||''};const preview=(a:any)=>uni.navigateTo({url:`/pages/preview/index?id=${a.id}&title=${encodeURIComponent(a.title||'3D模型')}`});const copy=(a:any)=>uni.setClipboardData({data:String(a.assetNo||a.id)});onMounted(async()=>{if(!requireSession())return;try{assets.value=await getAssets()}catch(e:any){uni.showToast({title:e.message||'加载作品失败',icon:'none'})}finally{loading.value=false}});</script>
<style scoped lang="scss">.page{min-height:100vh;padding:34rpx}.intro{padding:20rpx 4rpx 34rpx}.title{font-size:48rpx;font-weight:800;display:block}.sub{font-size:24rpx;color:#8e7469;display:block;margin-top:12rpx}.empty{padding:130rpx 40rpx;text-align:center;color:#9c8479}.asset{display:flex;background:#fff;border-radius:22rpx;margin-bottom:22rpx;overflow:hidden;box-shadow:0 8rpx 22rpx rgba(65,34,20,.07)}.cover,.model{width:180rpx;height:180rpx;flex-shrink:0}.model{background:linear-gradient(145deg,#4b2518,#bc5a34);color:#fff;font-size:38rpx;font-weight:800;display:flex;align-items:center;justify-content:center}.body{padding:20rpx;min-width:0;flex:1}.row{display:flex;align-items:center;gap:12rpx}.name{font-weight:700;font-size:29rpx;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.status{font-size:20rpx;border-radius:20rpx;padding:6rpx 12rpx;background:#f9e6d5;color:#a2492b}.status.approved,.status.succeeded{background:#e4f5e9;color:#248653}.meta,.source{display:block;font-size:21rpx;color:#967c70;margin-top:10rpx}.source{color:#9d4e30;white-space:normal}.actions{margin-top:14rpx}.actions button{margin:0 12rpx 0 0;background:#f8ede5;color:#843b23;font-size:20rpx}</style>
